SELECT t0.name AS "Name",t1.amount AS "Orders Amount" FROM (SELECT t2.id AS "customer_id",t2.name AS "name",'retail' AS "_set" FROM org.retail_customers AS t2 UNION ALL SELECT t3.id AS "customer_id",t3.name AS "name",'corporate' AS "_set" FROM org.corporate_customers AS t3) AS t0 LEFT OUTER JOIN org.orders AS t1 ON (t0.customer_id = t1.customer_id AND t0._set = 'retail') ORDER BY t0.name ASC NULLS FIRST
